using UnityEngine;
namespace CatGames {
 // Original racing frames with local mesh deformation only on the painted tail.
 public sealed class CatTailMesh {
  static readonly Vector2[][] Paths={new[]{new Vector2(94,173),new Vector2(78,178),new Vector2(60,193),new Vector2(43,202),new Vector2(28,203)},new[]{new Vector2(124,194),new Vector2(115,198),new Vector2(107,209),new Vector2(106,220)},new[]{new Vector2(141,181),new Vector2(149,191),new Vector2(153,203),new Vector2(150,213)},new[]{new Vector2(94,184),new Vector2(82,194),new Vector2(72,208),new Vector2(59,218),new Vector2(48,219)},new[]{new Vector2(136,193),new Vector2(127,204),new Vector2(113,215),new Vector2(101,220)},new[]{new Vector2(109,207),new Vector2(96,218),new Vector2(78,229),new Vector2(60,232),new Vector2(46,231)}};
  readonly GameObject obj;readonly Mesh mesh;readonly MeshRenderer renderer;readonly Vector3[] vertices=new Vector3[1089];readonly Vector2[] uv=new Vector2[1089];readonly MaterialPropertyBlock props=new MaterialPropertyBlock();int lastFrame=-1,lastRow=-1;
  public CatTailMesh(Transform parent,Texture texture){obj=new GameObject("Flexible painted tail",typeof(MeshFilter),typeof(MeshRenderer));obj.transform.SetParent(parent);mesh=new Mesh();mesh.MarkDynamic();obj.GetComponent<MeshFilter>().sharedMesh=mesh;renderer=obj.GetComponent<MeshRenderer>();renderer.sharedMaterial=CatSpriteEdges.Material;props.SetTexture("_MainTex",texture);int[] triangles=new int[32*32*6];var colors=new Color[vertices.Length];for(int i=0;i<colors.Length;i++)colors[i]=Color.white;int k=0;for(int y=0;y<32;y++)for(int x=0;x<32;x++){int i=y*33+x;triangles[k++]=i;triangles[k++]=i+1;triangles[k++]=i+33;triangles[k++]=i+1;triangles[k++]=i+34;triangles[k++]=i+33;}mesh.vertices=vertices;mesh.colors=colors;mesh.triangles=triangles;}
  public static Vector2 Bend(int frame,Vector2 point,float time,float amount,float turn){var path=Paths[frame];float length=0;for(int i=1;i<path.Length;i++)length+=Vector2.Distance(path[i-1],path[i]);float distance=float.MaxValue,u=0,start=0;for(int i=1;i<path.Length;i++){var d=path[i]-path[i-1];float len=d.magnitude,t=Mathf.Clamp01(Vector2.Dot(point-path[i-1],d)/d.sqrMagnitude),dist=Vector2.Distance(point,path[i-1]+d*t);if(dist<distance){distance=dist;u=(start+len*t)/length;}start+=len;}float edge=Mathf.Clamp01((22-distance)/12),root=Mathf.Clamp01((u-.16f)/.84f),weight=root*root*(3-2*root)*edge*edge*(3-2*edge),phase=time*6.2f-u*2.3f;return point+new Vector2(weight*(Mathf.Sin(phase)*2*amount+Mathf.Clamp(turn,-1,1)*3),weight*Mathf.Sin(phase-.65f)*4.8f*amount);}
  public void Hide(){renderer.enabled=false;}
  public void Draw(int row,int frame,float x,float foot,float size,float time,float amount,float turn,float alpha,int order){renderer.enabled=true;renderer.sortingOrder=order;bool changed=frame!=lastFrame||row!=lastRow;for(int y=0;y<=32;y++)for(int xx=0;xx<=32;xx++){int i=y*33+xx;var p=Bend(frame,new Vector2(xx*8,y*8),time,amount,amount==0?0:turn);vertices[i]=new Vector3(p.x-128,242-p.y,0);if(changed)uv[i]=new Vector2((frame*256+xx*8)/1536f,1-(row*256+y*8)/1024f);}mesh.vertices=vertices;if(changed){mesh.uv=uv;lastFrame=frame;lastRow=row;props.SetVector("_FrameUV",new Vector4(frame/6f,1-(row+1)/4f,(frame+1)/6f,1-row/4f));}mesh.RecalculateBounds();obj.transform.position=new Vector3(x-300,CatPaint.ViewHeight/2-foot,0);obj.transform.localScale=Vector3.one*(size/256);props.SetColor("_Color",new Color(1,1,1,alpha));renderer.SetPropertyBlock(props);}
 }
}
